import {startCloudSync,stopCloudSync,queueSync,observeCloudStatus,syncNow} from './cloud-db.js';
import {generateCourse,readGenerated,saveGenerated} from './any-topic.js';
import {courses,allLessons,courseById,courseForLesson,findCourse,allScenarios} from './catalog.js';
import {authReady,authLoaded,user,initAuth,register,login,logout,resetPassword,readableAuthError,subscribeAuth} from './auth.js';
import {languages,lessons,scenarios,diagnostic,t,loc} from './content.js';
import {readState,writeState,registerWorker,cachePack,exportProgress} from './offline.js';
const $=sel=>document.querySelector(sel);
const defaults={lang:'en',name:'',goal:'cs',level:'beginner',minutes:10,onboarded:false,diagAnswers:{},diagnostic:null,completed:[],quizResults:{},practice:{},drafts:{},reviewDue:{},offlinePack:false};
let state={...defaults,...readState()};
let onboardingStep=0,activeQuizChoice=-1,scenarioChoice=-1,quizRevealed=false,scenarioRevealed=false,helperLesson=0,helperMode='hint',toastTimer=null;
const lang=()=>state.lang||'en';
const tr=k=>t(lang(),k);
const lc=v=>loc(v,lang());
const save=()=>{try{
 const uid=user()?.uid;
 if(uid){localStorage.setItem('skillbridge-state-user-'+uid,JSON.stringify(state));if(!user()?.offline)queueSync(uid)}
 else if(!writeState(state))notify(tr('saveFailed'),'error');
 }catch(err){console.error('Local progress save failed',err);notify(tr('saveFailed'),'error')}
};
const course=()=>courseById(state.goal);
const courseLessons=()=>course().lessons;
const courseScenarios=()=>allScenarios.filter(x=>!x.track?state.goal==='cs':x.track===state.goal);
const courseDone=()=>courseLessons().filter(l=>state.completed.includes(l.id)).length;
const dueLessons=()=>allLessons.filter(l=>state.completed.includes(l.id)&&state.reviewDue?.[l.id]&&state.reviewDue[l.id].due<=Date.now());
const planReview=id=>{const old=state.reviewDue?.[id],stage=Math.min((old?.stage||0)+1,5),days=[0,1,3,7,14,30][stage];state.reviewDue={...(state.reviewDue||{}),[id]:{stage,due:Date.now()+days*86400000,last:Date.now()}}};
const generated=()=>readGenerated(user()?.uid||'guest');
let generating=false,generatedError='',generatedStatus='';
const stateForAccount=uid=>{if(!uid)return {...defaults,...readState()};try{const stored=JSON.parse(localStorage.getItem('skillbridge-state-user-'+uid)||'null');if(stored)return {...defaults,...stored}}catch{}return {...defaults,lang:state.lang||'en'}};

